"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0db/refs"
import { cn } from "@/lib/utils"

const clock = (n: number) => `${Math.floor(n / 60)}:${String(Math.floor(n % 60)).padStart(2, "0")}`
type AudioPlayerProps = Omit<React.ComponentProps<"div">, "children"> & {
  src: string
  label: string
  audioProps?: Omit<React.ComponentProps<"audio">, "src" | "controls" | "autoPlay" | "children">
  onTimeChange?: (seconds: number) => void
  playLabel?: string
  pauseLabel?: string
  seekLabel?: string
  errorLabel?: string
  disabled?: boolean
}

/** A recording on its own baseline. The audio ref permits a transcript or another reader to seek it. */
function AudioPlayer(props: AudioPlayerProps) {
  return <AudioRecording key={props.src} {...props} />
}

function AudioRecording({ src, label, audioProps, onTimeChange, playLabel = "Play", pauseLabel = "Pause", seekLabel = "Seek in recording", errorLabel = "Recording unavailable. Try Play again.", disabled, className, ...props }: AudioPlayerProps) {
  const id = React.useId()
  const audio = React.useRef<HTMLAudioElement>(null)
  const [state, setState] = React.useState({ src, time: 0, duration: 0, playing: false, error: false })
  const attach = React.useCallback((el: HTMLAudioElement | null) => {
    audio.current = el
    // Prerendered media can load or fail before React attaches its event handlers.
    if (el) {
      const next = { src, time: Number.isFinite(el.currentTime) ? el.currentTime : 0, duration: Number.isFinite(el.duration) ? el.duration : 0, playing: !el.paused, error: Boolean(el.error) }
      setState((previous) => Object.keys(next).every((key) => previous[key as keyof typeof next] === next[key as keyof typeof next]) ? previous : next)
    }
  }, [src])
  const audioRef = useComposedRefs(attach, audioProps?.ref)
  const current = state.src === src ? state : { src, time: 0, duration: 0, playing: false, error: false }
  const sample = (el: HTMLAudioElement) => {
    if (el !== audio.current) return
    const time = Number.isFinite(el.currentTime) ? el.currentTime : 0
    setState({ src, time, duration: Number.isFinite(el.duration) ? el.duration : 0, playing: !el.paused, error: Boolean(el.error) })
    onTimeChange?.(time)
  }
  React.useEffect(() => {
    const el = audio.current
    return () => { el?.pause() }
  }, [])
  React.useEffect(() => { if (disabled) audio.current?.pause() }, [disabled])
  return <div {...props} data-slot="audio-player" data-playing={current.playing ? "" : undefined} className={cn("db-audio", className)}>
    <span data-slot="audio-title" className="db-audio-title" id={`${id}-title`}>{label}</span>
    <audio {...audioProps} key={src} ref={audioRef} data-slot="audio-native" src={src} autoPlay={false} controls={false} preload={audioProps?.preload ?? "metadata"} aria-label={audioProps?.["aria-label"] ?? label}
      onLoadedMetadata={(e) => { audioProps?.onLoadedMetadata?.(e); sample(e.currentTarget) }}
      onDurationChange={(e) => { audioProps?.onDurationChange?.(e); sample(e.currentTarget) }}
      onTimeUpdate={(e) => { audioProps?.onTimeUpdate?.(e); sample(e.currentTarget) }}
      onPlay={(e) => { audioProps?.onPlay?.(e); sample(e.currentTarget) }}
      onPause={(e) => { audioProps?.onPause?.(e); sample(e.currentTarget) }}
      onEnded={(e) => { audioProps?.onEnded?.(e); sample(e.currentTarget) }}
      onError={(e) => { audioProps?.onError?.(e); sample(e.currentTarget) }} />
    <div className="db-audio-face">
      <button type="button" data-slot="audio-play" disabled={disabled} aria-label={`${current.playing ? pauseLabel : playLabel} ${label}`} onClick={async () => {
        const el = audio.current
        if (!el) return
        if (!el.paused) el.pause()
        else {
          try { if (el.error) el.load(); await el.play() }
          catch { if (el === audio.current) setState((s) => ({ ...s, src, error: true })) }
        }
      }}>{current.playing ? pauseLabel : playLabel}<span className="db-audio-hold" aria-hidden="true" /></button>
      <span data-slot="audio-time" className="db-audio-time" aria-hidden="true"><bdi dir="ltr" className="db-yours">{clock(current.time)}</bdi><small> / <bdi dir="ltr">{clock(current.duration)}</bdi></small></span>
    </div>
    <label className="db-sr" htmlFor={`${id}-seek`}>{seekLabel}: {label}</label>
    <div className="db-audio-track" style={{ "--db-audio-progress": current.duration ? Math.min(1, current.time / current.duration) : 0 } as React.CSSProperties}>
    <span className="db-audio-needle" aria-hidden="true" />
    <span className="db-audio-scale" aria-hidden="true"><span>00</span><span>{clock(current.duration / 4)}</span><span>{clock(current.duration / 2)}</span><span>{clock(current.duration * 3 / 4)}</span><span>{clock(current.duration)}</span></span>
    <input data-slot="audio-seek" className="db-audio-seek" id={`${id}-seek`} type="range" min={0} max={current.duration || 1} step={0.1} value={Math.min(current.time, current.duration || 1)} disabled={disabled || !current.duration} aria-valuetext={`${clock(current.time)} / ${clock(current.duration)}`} onChange={(e) => {
      const el = audio.current
      if (!el) return
      el.currentTime = Number(e.target.value)
      sample(el)
    }} />
    </div>
    {current.error ? <p data-slot="audio-error" className="db-audio-error" role="status">{errorLabel}</p> : null}
  </div>
}

export { AudioPlayer, type AudioPlayerProps }

@layer components {
  /* The media clock is a moving score. The title parts around it only while the recording is held. */
  .db-audio { min-inline-size: 0; overflow-wrap: anywhere; container-type: inline-size; }
  .db-audio-title { display: block; font-size: var(--db-pp); color: var(--db-graphite); margin-block-end: var(--db-space-5); max-inline-size: 40ch; }
  .db-audio-face { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: var(--db-space-4); }
  .db-audio-face > button { grid-column: 2; grid-row: 1; position: relative; background: none; border: 0; min-block-size: 48px; padding: var(--db-space-3) 0; cursor: pointer; font-size: var(--db-p); color: var(--db-ink); min-inline-size: 4rem; text-align: end; }
  .db-audio-hold { position: absolute; inset-block-start: -0.75rem; inset-inline: 0; block-size: 1rem; border: var(--db-hairline) solid var(--db-pencil); border-block-end: 0; border-radius: 50% 50% 0 0; transform: scaleY(0.15) rotate(-8deg); transform-origin: center bottom; transition: transform var(--db-andante) var(--db-spiccato); }
  .db-audio[data-playing] .db-audio-hold { transform: scaleY(1) rotate(0deg); border-color: var(--db-rule-strong); }
  .db-audio-time { grid-column: 1; grid-row: 1; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--db-space-3); font-size: clamp(4rem, 20cqi, 8rem); color: var(--db-ink); line-height: 1.1; letter-spacing: -0.065em; font-variant-numeric: tabular-nums; }
  .db-audio-time > bdi { display: inline-block; transform-origin: left bottom; transition: transform var(--db-andante) var(--db-spiccato), letter-spacing var(--db-andante) var(--db-exhale); }
  .db-audio[data-playing] .db-audio-time > bdi { transform: skewX(-4deg); letter-spacing: -0.04em; }
  .db-audio-time small { font-size: var(--db-pp); font-family: var(--db-voice); font-style: normal; color: var(--db-pencil); letter-spacing: 0; white-space: nowrap; }
  .db-audio-track { position: relative; margin-block-start: var(--db-space-5); block-size: 3.5rem; border-block-start: var(--db-hairline) solid var(--db-rule-strong); }
  .db-audio-track::before { content: ""; position: absolute; inset-inline-start: 0; inset-block-start: -1px; inline-size: calc(var(--db-audio-progress, 0) * 100%); border-block-start: var(--db-hairline) solid var(--db-ink); }
  .db-audio-needle { position: absolute; inset-inline-start: calc(var(--db-audio-progress, 0) * 100%); inset-block-start: -0.75rem; block-size: 1.5rem; border-inline-start: var(--db-hairline) solid var(--db-accent); pointer-events: none; transition: block-size var(--db-andante) var(--db-spiccato), inset-block-start var(--db-andante) var(--db-spiccato); }
  .db-audio[data-playing] .db-audio-needle { block-size: 2.5rem; inset-block-start: -1.25rem; }
  .db-audio-scale { display: flex; justify-content: space-between; font-size: 0.65rem; color: var(--db-pencil); padding-block-start: 1.25rem; pointer-events: none; }
  .db-audio-seek { position: absolute; inset: -1.3rem 0 0; display: block; appearance: none; background: transparent; inline-size: 100%; block-size: 44px; margin: 0; cursor: pointer; }
  .db-audio-seek::-webkit-slider-runnable-track { block-size: var(--db-hairline); background: transparent; }
  .db-audio-seek::-moz-range-track { block-size: var(--db-hairline); background: transparent; }
  .db-audio-seek::-webkit-slider-thumb { appearance: none; inline-size: 14px; block-size: 28px; border: 0; background: transparent; margin-block-start: -14px; }
  .db-audio-seek::-moz-range-thumb { inline-size: 14px; block-size: 28px; border: 0; background: transparent; }
  .db-audio-face > button:disabled, .db-audio-seek:disabled { cursor: default; color: var(--db-pencil); }
  .db-audio-error { color: var(--db-signal); font-size: var(--db-pp); }
  @container (max-width: 330px) { .db-audio-time { font-size: 3.8rem; } .db-audio-face { gap: var(--db-space-2); } .db-audio-face > button { min-inline-size: 3rem; } }
  @media (prefers-reduced-motion: reduce) { .db-audio-hold, .db-audio-time > bdi, .db-audio-needle { transition: none; } }
  @media (forced-colors: active) { .db-audio-seek { appearance: auto; } .db-audio-needle { border-color: Highlight; } }
}
